/**
 * Meta Options build.
 */
import { PluginSidebar } from '@wordpress/edit-post';
import { __ } from '@wordpress/i18n';
import { Component, Fragment } from '@wordpress/element';
import { PanelBody, TextControl, SelectControl } from '@wordpress/components';
import { withSelect, withDispatch } from '@wordpress/data';
import { compose } from '@wordpress/compose';

class Sidebar extends Component {
	constructor() {
		super(...arguments);
		this.state = {};
	}

	render() {
		const { meta, setMetaFieldValue, posts, postType } = this.props;

		// Don't render if not our post type
		if (postType !== 'review') {
			return null;
		}

		// Prepare product options for SelectControl
		const productOptions = [
			{ label: __('Select a Item', 'blank-plugin'), value: '' },
			...posts.map((product) => ({
				label: product.title.rendered,
				value: product.id,
			})),
		];

		return (
			<Fragment>
				<PluginSidebar
					name="blank-plugin-sidebar"
					title={__('Blank Plugin', 'blank-plugin')}
				>
					<PanelBody title={__('Review Details', 'blank-plugin')}>
						<SelectControl
							label={__('Review Item', 'blank-plugin')}
							value={meta.review_item || ''}
							options={productOptions}
							onChange={(value) =>
								setMetaFieldValue(value, 'review_item')
							}
						/>
						<SelectControl
							label={__('Rating (1–5)', 'blank-plugin')}
							value={meta.reviewer_rating || ''}
							options={[
								{
									label: __('Select Rating', 'blank-plugin'),
									value: '',
								},
								{ label: '1', value: '1' },
								{ label: '2', value: '2' },
								{ label: '3', value: '3' },
								{ label: '4', value: '4' },
								{ label: '5', value: '5' },
							]}
							onChange={(value) =>
								setMetaFieldValue(value, 'reviewer_rating')
							}
						/>
						<TextControl
							label={__("Reviewer's Name", 'blank-plugin')}
							value={meta.reviewer_name || ''}
							onChange={(value) =>
								setMetaFieldValue(value, 'reviewer_name')
							}
						/>
					</PanelBody>
				</PluginSidebar>
			</Fragment>
		);
	}
}

export default compose(
	withSelect((select) => {
		// Retrieve the current post's saved meta
		const postMeta = select('core/editor').getEditedPostAttribute('meta');
		const oldPostMeta =
			select('core/editor').getCurrentPostAttribute('meta');

		// Fetch the current post type
		const postType = select('core/editor').getEditedPostAttribute('type');
		// Fetch all WooCommerce posts
		const posts =
			select('core').getEntityRecords('postType', 'post', {
				per_page: -1, // Retrieve all posts
				status: 'publish', // Only published posts
			}) || [];

		return {
			meta: { ...oldPostMeta, ...postMeta },
			oldMeta: oldPostMeta,
			posts,
			postType,
		};
	}),
	withDispatch((dispatch) => ({
		setMetaFieldValue: (value, field) =>
			dispatch('core/editor').editPost({ meta: { [field]: value } }),
	}))
)(Sidebar);
